INSERT INTO public.american_lessons (id,book_no,unit_no,lesson_no,title_en,title_cn,grammar_focus,scene,prelisten_question,grammar_card) VALUES ('am2_l49',2,7,49,'The end of a dream','美梦告终','复合句/从属连词(教材 Unit 3 主考:用 when/as/while/because/although/until/after 把简单句连成复合句)——because 原因、when 时间、although 让步、not…until 直到才、after 先后;be tired of、save up、blow up、send sth doing(辅考·课文①类)','德黑兰的一个年轻人厌倦了睡地板,攒了多年的钱买了一张真正的床。他平生第一次自豪地拥有了一张既有弹簧又带床垫的床。由于天气很热,他把床搬到了屋顶上。头两晚他睡得非常好,但第三天夜里刮起了风暴。一阵大风把床从屋顶上刮了下来,把它摔碎在下面的院子里。年轻人直到床撞到地上才醒了过来。尽管床摔得粉碎,他却奇迹般地毫发无伤——醒来时还在床垫上。他望着四周的木片和金属碎片,伤心地捡起床垫搬回屋里;把床垫放到地板上后,又立刻睡着了。','{"q":"Listen and answer — How did the dream end?","options":["A storm swept the new bed off the roof and smashed it to pieces","He slept peacefully on it for years","He gave the bed away","The bed was stolen"],"answer_index":0}'::jsonb,'{"title":"复合句:用从属连词连接两个句子","intro":"从这一单元起,学习用从属连词把两个简单句连成一个复合句:because(因为)、when(当…时)、although(虽然)、until(直到)、after(在…之后)。连词引导的部分叫从句,可放主句前面或后面。全用本课句子举例。","table":{"headers":["连词","例子"],"rows":[["because(因为)","Because the weather was hot, he carried the bed onto the roof."],["when(当…时)","When he woke up, he was still on the mattress."],["although(虽然)","Although the bed was smashed, the man was unhurt."],["not…until(直到…才)","He did not wake up until the bed had struck the ground."],["after(在…之后)","After he had put it on the floor, he went to sleep."]]},"specialRules":[{"rule":"not…until 表''直到…才…'':He did not wake up until the bed had struck the ground(直到床落地他才醒)。","mark":"not…until = 直到才"},{"rule":"although(虽然)不能和 but 连用:Although…, the man was unhurt(不能写成 Although…, but…)。","mark":"although 不配 but"}]}'::jsonb) ON CONFLICT (id) DO UPDATE SET book_no=EXCLUDED.book_no,title_en=EXCLUDED.title_en,title_cn=EXCLUDED.title_cn,grammar_focus=EXCLUDED.grammar_focus,scene=EXCLUDED.scene,prelisten_question=EXCLUDED.prelisten_question,grammar_card=EXCLUDED.grammar_card;
INSERT INTO public.american_sentences (lesson_id,seq,speaker,text_en,text_cn) VALUES ('am2_l49',1,NULL,'Tired of sleeping on the floor, a young man in Tehran saved up for years to buy a real bed.','厌倦了睡地板,德黑兰的一个年轻人攒了多年的钱买了一张真正的床。') ON CONFLICT (lesson_id,seq) DO UPDATE SET speaker=EXCLUDED.speaker,text_en=EXCLUDED.text_en,text_cn=EXCLUDED.text_cn;
INSERT INTO public.american_sentences (lesson_id,seq,speaker,text_en,text_cn) VALUES ('am2_l49',2,NULL,'For the first time in his life, he became the proud owner of a bed which had springs and a mattress.','他平生第一次自豪地拥有了一张既有弹簧又带床垫的床。') ON CONFLICT (lesson_id,seq) DO UPDATE SET speaker=EXCLUDED.speaker,text_en=EXCLUDED.text_en,text_cn=EXCLUDED.text_cn;
INSERT INTO public.american_sentences (lesson_id,seq,speaker,text_en,text_cn) VALUES ('am2_l49',3,NULL,'Because the weather was very hot, he carried the bed onto the roof of his house.','由于天气很热,他把床搬到了屋顶上。') ON CONFLICT (lesson_id,seq) DO UPDATE SET speaker=EXCLUDED.speaker,text_en=EXCLUDED.text_en,text_cn=EXCLUDED.text_cn;
INSERT INTO public.american_sentences (lesson_id,seq,speaker,text_en,text_cn) VALUES ('am2_l49',4,NULL,'He slept very well for the first two nights, but on the third night, a storm blew up.','头两晚他睡得非常好,但第三天夜里刮起了风暴。') ON CONFLICT (lesson_id,seq) DO UPDATE SET speaker=EXCLUDED.speaker,text_en=EXCLUDED.text_en,text_cn=EXCLUDED.text_cn;
INSERT INTO public.american_sentences (lesson_id,seq,speaker,text_en,text_cn) VALUES ('am2_l49',5,NULL,'A gust of wind swept the bed off the roof and sent it crashing into the courtyard below.','一阵大风把床从屋顶上刮了下来,把它摔碎在下面的院子里。') ON CONFLICT (lesson_id,seq) DO UPDATE SET speaker=EXCLUDED.speaker,text_en=EXCLUDED.text_en,text_cn=EXCLUDED.text_cn;
INSERT INTO public.american_sentences (lesson_id,seq,speaker,text_en,text_cn) VALUES ('am2_l49',6,NULL,'The young man did not wake up until the bed had struck the ground.','年轻人直到床撞到地上才醒了过来。') ON CONFLICT (lesson_id,seq) DO UPDATE SET speaker=EXCLUDED.speaker,text_en=EXCLUDED.text_en,text_cn=EXCLUDED.text_cn;
INSERT INTO public.american_sentences (lesson_id,seq,speaker,text_en,text_cn) VALUES ('am2_l49',7,NULL,'Although the bed was smashed to pieces, the man was miraculously unhurt. When he woke up, he was still on the mattress.','尽管床摔得粉碎,他却奇迹般地毫发无伤;醒来时还在床垫上。') ON CONFLICT (lesson_id,seq) DO UPDATE SET speaker=EXCLUDED.speaker,text_en=EXCLUDED.text_en,text_cn=EXCLUDED.text_cn;
INSERT INTO public.american_sentences (lesson_id,seq,speaker,text_en,text_cn) VALUES ('am2_l49',8,NULL,'Glancing at the bits of wood and metal that lay around him, the man sadly picked up the mattress and carried it into his house. After he had put it on the floor, he promptly went to sleep again.','他望着四周的木片和金属碎片,伤心地捡起床垫搬回屋里;放到地板上后,又立刻睡着了。') ON CONFLICT (lesson_id,seq) DO UPDATE SET speaker=EXCLUDED.speaker,text_en=EXCLUDED.text_en,text_cn=EXCLUDED.text_cn;
